15	enum class SerializationFormat : std::uint8_t {
16	    Binary = 0,
17	    Csv    = 1,
18	};
19	
20	struct DumpHeader {
21	    char          magic[24]    = {'C', 'O', 'M', 'D', 'A', 'R', 'E', '-', 'M', 'E', 'A',  'S',
22	                                  'U', 'R', 'E', 'M', 'E', 'N', 'T', '-', 'V', '1', '\0', '\0'};
23	    std::uint32_t version      = 1;
24	    std::uint64_t run_id       = 0;
25	    std::uint64_t timestamp_ns = 0;
26	    std::uint64_t platform_sig = 0;
27	    std::uint64_t record_count = 0;
28	    std::uint32_t record_size  = sizeof(MeasurementRecord);
29	};
30	
31	struct DumpFooter {
32	    std::uint64_t checksum       = 0;
33	    char          end_marker[12] = {'E', 'N', 'D', '-', 'C', 'O', 'M', 'D', 'A', 'R', 'E', '\0'};
34	};
35	
36	using RunId = std::uint64_t;
37	
38	class InMemoryMeasurementBuffer {
39	public:
40	    explicit InMemoryMeasurementBuffer(SerializationFormat fmt = SerializationFormat::Binary) : format_(fmt) {}
41	
42	    // Hot-Path: pro-Thread-Arena, kein Lock
43	    void append_record(MeasurementRecord const& record) noexcept {
44	        ThreadArena& a = arena_for_current_thread();
45	        a.append(record);
46	    }
47	
48	    [[nodiscard]] SerializationFormat format() const noexcept { return format_; }
49	
50	    [[nodiscard]] std::size_t total_records() const noexcept {
51	        std::size_t total = 0;
52	        for (auto const& [_, arena] : arenas_) total += arena.size();
53	        return total;
54	    }
55	
56	    [[nodiscard]] std::size_t arena_count() const noexcept { return arenas_.size(); }
57	
58	    void reset_for_run(RunId run_id) noexcept {
59	        run_id_ = run_id;
60	        for (auto& [_, arena] : arenas_) arena.reset();
61	    }
62	
63	    [[nodiscard]] RunId run_id() const noexcept { return run_id_; }
64	
65	    [[nodiscard]] DumpHeader make_dump_header(std::uint64_t platform_sig) const noexcept {
66	        DumpHeader h{};
67	        h.run_id       = run_id_;
68	        h.platform_sig = platform_sig;
69	        h.record_count = total_records();
70	        h.timestamp_ns = static_cast<std::uint64_t>(
71	            std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::system_clock::now().time_since_epoch())
72	                .count());
73	        return h;
74	    }
75	
76	    // Pro-Thread Arena (Lazy-Allocation; Lock NUR fuer Map-Insert, NICHT fuer Append)
77	    [[nodiscard]] ThreadArena& arena_for_current_thread() noexcept {
78	        std::thread::id tid = std::this_thread::get_id();
79	        {
80	            std::lock_guard<std::mutex> g(arena_map_mutex_);
81	            auto                        it = arenas_.find(tid);
82	            if (it == arenas_.end()) { it = arenas_.emplace(tid, ThreadArena{tid}).first; }
83	            return it->second;
84	        }
85	    }
86	
87	    [[nodiscard]] std::map<std::thread::id, ThreadArena> const& arenas() const noexcept { return arenas_; }
88	
89	private:
90	    SerializationFormat                    format_;
91	    RunId                                  run_id_ = 0;
92	    std::map<std::thread::id, ThreadArena> arenas_{};
93	    mutable std::mutex                     arena_map_mutex_{};
94	};
